import{_ as e,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Pesquisa rápida por nome ou CPF/CNPJ","description":"","frontmatter":{"title":"Pesquisa rápida por nome ou CPF/CNPJ","id":"eproc-pesquisa-rapida-avancada","plataforma":"eproc","grupo":"Pesquisa e filtros","plano":"free","desde":"1.1.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-pesquisa-rapida-avancada.md","filePath":"funcionalidades/eproc-pesquisa-rapida-avancada.md"}'),t={name:"funcionalidades/eproc-pesquisa-rapida-avancada.md"};function i(p,a,d,c,n,u){return o(),r("div",null,a[0]||(a[0]=[s('<h1 id="pesquisa-rapida-por-nome-ou-cpf-cnpj" tabindex="-1">Pesquisa rápida por nome ou CPF/CNPJ <a class="header-anchor" href="#pesquisa-rapida-por-nome-ou-cpf-cnpj" aria-label="Permalink to &quot;Pesquisa rápida por nome ou CPF/CNPJ&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O campo de pesquisa rápida do menu lateral do eproc só aceita número de processo. Com este recurso, ele também aceita o nome da parte ou o CPF/CNPJ: o eploc leva a pesquisa para a consulta processual e já a executa.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, campo de pesquisa rápida do menu lateral.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Digite no campo de pesquisa rápida: <ul><li>um número de processo, para pesquisar como sempre;</li><li>um CPF ou CNPJ (com ou sem pontuação), por exemplo <code>000.000.000-00</code>;</li><li>ou um nome, por exemplo <code>Maria da Silva</code>.</li></ul></li><li>Tecle Enter ou clique na lupa.</li><li>O eploc abre a consulta processual, escolhe o tipo de pesquisa certo, preenche o campo e clica em Consultar.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Na pesquisa por nome, marcar automaticamente &quot;Selecionar todos&quot; no filtro de tipo de parte</td><td>desligada</td><td>A pesquisa por nome procura em todos os tipos de parte.</td></tr><tr><td>Repetir automaticamente a pesquisa quando o eproc a cancelar por &quot;mudança no perfil do usuário&quot; (ex.: logo após migrar processos)</td><td>ligada</td><td>Quando o eproc cancela a pesquisa com esse aviso, o eploc a refaz sozinho.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O formato &quot;número/ano&quot; (como <code>1000713/26</code>) é tratado pelo <a href="./eproc-autocomplete-cnj">Completar número do processo CNJ automaticamente</a>, e não como nome.</li><li>A pesquisa usa a página de consulta processual configurada como padrão no seu eproc.</li></ul>',11)]))}const q=e(t,[["render",i]]);export{m as __pageData,q as default};
